ALTER TABLE site_work_items ADD COLUMN IF NOT EXISTS origin_correlation_id TEXT;
COMMENT ON COLUMN site_work_items.origin_correlation_id IS
  'Correlation id of the orchestration run whose findings created this item, stored VERBATIM. Joins to llm_call_log.correlation_id (varchar) and orchestration_states.correlation_id (uuid - cast at query time). TEXT, not UUID: a parse step here could only ever turn a real origin into an indistinguishable NULL. Mirrors diagnosis_artifacts.correlation_id. NULL = created before 2026-07 or by a path with no originating run.';

-- Partial: only non-NULL rows are ever joined on, and the column stays
-- mostly NULL for historical rows.
CREATE INDEX IF NOT EXISTS idx_swi_origin_correlation
  ON site_work_items (origin_correlation_id)
  WHERE origin_correlation_id IS NOT NULL;

     _, err := params.DB.ExecContext(ctx, `
       INSERT INTO site_work_items (
         site_id, source, pipeline, item_type, severity, summary,
         spec, page_id, priority, handler_agent, status, created_by,
-        item_key, batch_id
-      ) VALUES ($1, $2, 'build', $3, $4, $5, $6::jsonb, $7, $8, $9, 'detected', $10, $11, $12)
+        item_key, batch_id, origin_correlation_id
+      ) VALUES ($1, $2, 'build', $3, $4, $5, $6::jsonb, $7, $8, $9, 'detected', $10, $11, $12, $13)
     `, siteID, "discovery", classified.ItemType, classified.Severity,
       f.Description, string(specJSON), classified.PageID, classified.Priority,
-      classified.HandlerAgent, auditSource, classified.DedupKey, batchID)
+      classified.HandlerAgent, auditSource, classified.DedupKey, batchID,
+      originCorrelationID)

// once above the loop - no parse, so no silent-null path:
//   var originCorrelationID interface{}   // nil -> SQL NULL
//   if params.ExecutionContext != nil && params.ExecutionContext.CorrelationID != "" {
//     originCorrelationID = params.ExecutionContext.CorrelationID
//   }

-- VERIFY (run after apply; all three must hold)
SELECT column_name, data_type, is_nullable FROM information_schema.columns
 WHERE table_name='site_work_items' AND column_name='origin_correlation_id';
  -- expect: origin_correlation_id | text | YES
SELECT indexname FROM pg_indexes
 WHERE tablename='site_work_items' AND indexname='idx_swi_origin_correlation';
  -- expect: 1 row
SELECT count(*) AS should_be_zero FROM site_work_items WHERE origin_correlation_id IS NOT NULL;
  -- expect: 0 until the new image rolls (Go change is inert until then)

-- ROLLBACK (safe: no data is mutated by this migration)
DROP INDEX IF EXISTS idx_swi_origin_correlation;
ALTER TABLE site_work_items DROP COLUMN IF EXISTS origin_correlation_id;
